import{_ as r,C as d,o as a,c as l,a4 as o,E as i}from"./chunks/framework.DAD9IEko.js";const C=JSON.parse('{"title":"路径11: FOC从仿真到固件","description":"","frontmatter":{"date":"2026-06-04T00:00:00.000Z","section":"电机控制","chapter":"practice","chapterTitle":"工程实践","chapterOrder":20,"category":"工程实践","source":"motor","visibility":"public","title":"路径11: FOC从仿真到固件","tags":["motor-control"],"status":"learning","summary":"> 来源：foc_controller-master | 前置：路径4(算法)站0-3 | 难度：~","navGroup":"实践与验证","navGroupOrder":40},"headers":[],"relativePath":"content/motor/practice/PRACTICE-11-FOC-Engineering.md","filePath":"content/motor/practice/PRACTICE-11-FOC-Engineering.md","lastUpdated":1783181958000}'),n={name:"content/motor/practice/PRACTICE-11-FOC-Engineering.md"};function s(c,t,p,h,_,E){const e=d("MermaidDiagram");return a(),l("div",null,[t[0]||(t[0]=o('<h1 id="路径11-foc从仿真到固件" tabindex="-1">路径11: FOC从仿真到固件 <a class="header-anchor" href="#路径11-foc从仿真到固件" aria-label="Permalink to &quot;路径11: FOC从仿真到固件&quot;">​</a></h1><blockquote><p>来源：foc_controller-master | 前置：路径4(算法)站0-3 | 难度：~</p></blockquote><h2 id="_1-路径概述" tabindex="-1">1. 路径概述 <a class="header-anchor" href="#_1-路径概述" aria-label="Permalink to &quot;1. 路径概述&quot;">​</a></h2><p>从Matlab仿真参数设计到STM32固件实现的FOC完整闭环。适合已掌握FOC理论基础（ALG-01/ALG-03）的学习者，通过&quot;理论→仿真→代码&quot;三步走，建立从公式到工程的完整认知。</p><p><strong>前置知识：</strong> 路径4(算法)站0-3（FOC理论、PI调节器、有感FOC） <strong>学习目标：</strong> 独立完成从Matlab仿真参数设计到STM32固件实现的完整FOC开发流程</p><h2 id="_2-学习路径图" tabindex="-1">2. 学习路径图 <a class="header-anchor" href="#_2-学习路径图" aria-label="Permalink to &quot;2. 学习路径图&quot;">​</a></h2>',6)),i(e,{code:"graph%20LR%0A%20%20%20%20A%5B%E7%AB%991%3A%20FOC%E8%AF%BE%E7%A8%8B%E6%A6%82%E8%BF%B0%5D%20--%3E%20B%5B%E7%AB%992%3A%20%E7%94%B5%E6%9C%BA%E5%8E%9F%E7%90%86%E4%B8%8E%E7%A1%AC%E4%BB%B6%E5%B9%B3%E5%8F%B0%5D%0A%20%20%20%20B%20--%3E%20C%5B%E7%AB%993%3A%20%E7%94%B5%E6%B5%81%E7%8E%AFPI%E8%AE%BE%E8%AE%A1%E4%B8%8E%E4%BB%BF%E7%9C%9F%5D%0A%20%20%20%20C%20--%3E%20D%5B%E7%AB%994%3A%20%E4%BD%8E%E9%80%9A%E6%BB%A4%E6%B3%A2%E5%99%A8%E8%AE%BE%E8%AE%A1%5D%0A%20%20%20%20C%20--%3E%20E%5B%E7%AB%995%3A%20FOC%E7%B3%BB%E7%BB%9F%E6%95%B4%E5%90%88%E4%B8%8ESVPWM%5D%0A%20%20%20%20D%20--%3E%20E%0A%20%20%20%20E%20--%3E%20F%5B%E7%AB%996%3A%20PLL%E8%A7%92%E5%BA%A6%E8%A7%82%E6%B5%8B%E5%99%A8%E4%B8%8E%E9%80%9F%E5%BA%A6%E7%8E%AF%5D%0A"}),t[1]||(t[1]=o('<h2 id="_3-站点详情表" tabindex="-1">3. 站点详情表 <a class="header-anchor" href="#_3-站点详情表" aria-label="Permalink to &quot;3. 站点详情表&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>站号</th><th>主题</th><th>资源引用</th><th>交叉引用KB模块</th><th>难度</th><th>预计学习时间</th></tr></thead><tbody><tr><td>站1</td><td>FOC课程概述</td><td><code>FOC_CourseDescription.pptx</code>FOC_CourseDescription.pptx)</td><td>ALG-01(FOC理论)</td><td></td><td>1-2小时</td></tr><tr><td>站2</td><td>电机原理与硬件平台</td><td><code>FOC_Motor&amp;Hw.pptx</code>FOC_Motor%26Hw.pptx) + <code>HW补充.pptx</code>HW补充.pptx)</td><td>HW-01(电机本体), HW-03(位置传感器), HW-05(功率器件)</td><td></td><td>2-3小时</td></tr><tr><td>站3</td><td>电流环PI设计与仿真</td><td><code>FOC_ClassicControl.pptx</code>FOC_ClassicControl.pptx) + <code>current_pi.m</code> + <code>pi_current.slx</code> + <code>current_pi_with_delay.m</code></td><td>ALG-03(PI调节器), ALG-01(FOC理论)</td><td></td><td>4-5小时</td></tr><tr><td>站4</td><td>低通滤波器设计</td><td><code>FOC_LowPassFilter.pptx</code>FOC_LowPassFilter.pptx) + <code>lpf2.m</code> + <code>lpf.slx</code></td><td>ADV-ALG-01(带宽与滤波器)</td><td></td><td>2-3小时</td></tr><tr><td>站5</td><td>FOC系统整合与SVPWM</td><td><code>FOC_Description.pptx</code>FOC_Description.pptx) + <code>FOC_SVPWM.pptx</code>FOC_SVPWM.pptx) + <code>motor_foc.slx</code> + <code>svpwm.slx</code></td><td>ALG-05(有感FOC)</td><td></td><td>4-5小时</td></tr><tr><td>站6</td><td>PLL角度观测器与速度环</td><td><code>pll.m</code> + <code>pll_angle.slx</code> + <code>speed_TI.m</code> + <code>mc_speed_TI.slx</code> + <code>pll.h</code> + <code>foc.c</code></td><td>ALG-06(位置速度观测器), ALG-12(速度环)</td><td></td><td>4-5小时</td></tr></tbody></table></div><h2 id="_4-各站详细说明" tabindex="-1">4. 各站详细说明 <a class="header-anchor" href="#_4-各站详细说明" aria-label="Permalink to &quot;4. 各站详细说明&quot;">​</a></h2><h3 id="站1-foc课程概述" tabindex="-1">站1: FOC课程概述 <a class="header-anchor" href="#站1-foc课程概述" aria-label="Permalink to &quot;站1: FOC课程概述&quot;">​</a></h3><ul><li><strong>核心要点：</strong> 了解FOC课程整体框架、学习路线和最终目标</li><li><strong>资源使用方法：</strong> 直接阅读PPT，了解后续各站的内容安排</li><li><strong>学习建议：</strong> 快速浏览即可，建立全局认知后进入站2</li></ul><h3 id="站2-电机原理与硬件平台" tabindex="-1">站2: 电机原理与硬件平台 <a class="header-anchor" href="#站2-电机原理与硬件平台" aria-label="Permalink to &quot;站2: 电机原理与硬件平台&quot;">​</a></h3><ul><li><strong>核心要点：</strong> PMSM数学模型(dq轴电压方程)、ODrive v3.6硬件平台(STM32F404 + DRV8301 + AS5047P)</li><li><strong>资源使用方法：</strong> 先看电机原理PPT，再看HW补充PPT了解硬件细节</li><li><strong>学习建议：</strong> 对照KB模块HW-01(电机本体)和HW-05(功率器件)加深理解</li></ul><h3 id="站3-电流环pi设计与仿真-核心站" tabindex="-1">站3: 电流环PI设计与仿真（核心站） <a class="header-anchor" href="#站3-电流环pi设计与仿真-核心站" aria-label="Permalink to &quot;站3: 电流环PI设计与仿真（核心站）&quot;">​</a></h3><ul><li><strong>核心要点：</strong> PI参数计算公式(Kp = W<em>Ls, Ki = W</em>Rs)、考虑延迟的电流环分析、Anti-windup设计</li><li><strong>资源使用方法：</strong> 先看PPT理解原理 → 运行current_pi.m计算参数 → 打开pi_current.slx验证 → 运行current_pi_with_delay.m分析延迟影响</li><li><strong>学习建议：</strong> 这是本路径最核心的一站，务必理解Kp/Ki与电感/电阻的物理关系。对照KB模块ALG-03(PI调节器)的带宽设计方法</li></ul><h3 id="站4-低通滤波器设计" tabindex="-1">站4: 低通滤波器设计 <a class="header-anchor" href="#站4-低通滤波器设计" aria-label="Permalink to &quot;站4: 低通滤波器设计&quot;">​</a></h3><ul><li><strong>核心要点：</strong> 一阶LPF参数设计(alpha = W<em>Ts/(1+W</em>Ts))，用于电流/速度信号滤波</li><li><strong>资源使用方法：</strong> 先看PPT → 运行lpf2.m → 打开lpf.slx验证</li><li><strong>学习建议：</strong> LPF是FOC系统中无处不在的模块，理解截止频率选择与信号延迟的权衡</li></ul><h3 id="站5-foc系统整合与svpwm" tabindex="-1">站5: FOC系统整合与SVPWM <a class="header-anchor" href="#站5-foc系统整合与svpwm" aria-label="Permalink to &quot;站5: FOC系统整合与SVPWM&quot;">​</a></h3><ul><li><strong>核心要点：</strong> Clarke/Park变换→PI控制→反Park→SVPWM完整链路、6扇区判断、占空比计算</li><li><strong>资源使用方法：</strong> 先看FOC_Description.pptx理解整体框架 → 看FOC_SVPWM.pptx深入SVPWM → 打开motor_foc.slx运行完整FOC仿真 → 打开svpwm.slx单独验证SVPWM</li><li><strong>学习建议：</strong> 这是系统整合的关键站，建议对照固件controller/foc.c中的foc_update_svpwm函数理解代码实现</li></ul><h3 id="站6-pll角度观测器与速度环" tabindex="-1">站6: PLL角度观测器与速度环 <a class="header-anchor" href="#站6-pll角度观测器与速度环" aria-label="Permalink to &quot;站6: PLL角度观测器与速度环&quot;">​</a></h3><ul><li><strong>核心要点：</strong> 二阶PLL带宽设计(Kp = 0.707*Wn, Ki = Wn^2/4.427)、TI风格速度环整定(阻尼因子Theta)</li><li><strong>资源使用方法：</strong> 运行pll.m设计PLL参数 → 打开pll_angle.slx验证 → 运行speed_TI.m设计速度环 → 打开mc_speed_TI.slx验证</li><li><strong>学习建议：</strong> PLL是编码器角度处理的关键模块，对照固件controller/pll.h理解C代码实现</li></ul><h2 id="_5-路径间关联" tabindex="-1">5. 路径间关联 <a class="header-anchor" href="#_5-路径间关联" aria-label="Permalink to &quot;5. 路径间关联&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>关联路径</th><th>关系</th><th>说明</th></tr></thead><tbody><tr><td>路径4(算法)站0-3</td><td>前置</td><td>需先掌握FOC理论和PI调节器基础</td></tr><tr><td>路径12(PMSM仿真)</td><td>并行/后续</td><td>学完站5后可开始路径12</td></tr><tr><td>路径14(工程实现)</td><td>后续</td><td>站4的固件架构可作为路径14的铺垫</td></tr><tr><td>路径9(C仿真)</td><td>替代</td><td>无MATLAB许可证时可用C仿真验证</td></tr></tbody></table></div><h2 id="_6-补充资源" tabindex="-1">6. 补充资源 <a class="header-anchor" href="#_6-补充资源" aria-label="Permalink to &quot;6. 补充资源&quot;">​</a></h2><ul><li><code>固件controller目录</code> — foc.c / pi.h / svpwm.c / pll.h 完整FOC算法实现</li><li><code>Papers目录</code> — 4篇参考论文（TI InstaSPIN、Microchip AN1078、霍尔安装误差、电流环延迟分析）</li><li><code>config.h</code> — 硬件参数配置（PWM频率、死区时间、引脚映射）</li><li><code>Keil工程</code> — odrive_mks.uvprojx</li></ul><h2 id="_7-常见问题" tabindex="-1">7. 常见问题 <a class="header-anchor" href="#_7-常见问题" aria-label="Permalink to &quot;7. 常见问题&quot;">​</a></h2><p><strong>Q: Simulink模型打开报错？</strong> A: 先运行对应目录下的.m脚本初始化参数，再打开.slx模型。例如站3需先运行current_pi.m再打开pi_current.slx。</p><p><strong>Q: 没有MATLAB许可证？</strong> A: 可使用知识库<a href="./../simulation/SIM-00-C-Simulation-Overview.html">路径9: C仿真验证</a>的C仿真平台替代，支持FOC/速度环/无感等算法验证。</p><p><strong>Q: 固件如何编译？</strong> A: 使用Keil uVision打开Projects目录下的odrive_mks.uvprojx工程文件，需要STM32F4 HAL库和ARM CMSIS支持。</p><p><strong>Q: 硬件平台与知识库HW模块的对应关系？</strong> A: ODrive v3.6使用STM32F404(HW-04 MCU外设) + DRV8301(HW-05 功率器件) + AS5047P(HW-03 位置传感器) + 下桥电流采样(HW-02 电流采样)。</p><p><strong>注意事项：</strong> 资源位置可能变化，请以实际路径为准。所有PPT和代码资源为中文。</p>',25))])}const P=r(n,[["render",s]]);export{C as __pageData,P as default};
